-- Remap classic profession trainers to the tier-0 TrainerIds.
-- Generated by tools/generate-profession-trainer-sql.py

-- Remember each NPC's TrainerId before the remap, so the uninstall script restores what the
-- server actually had (other modules, e.g. mod-individual-progression, change these too).
-- INSERT IGNORE keeps the first value seen if this file is applied again.
CREATE TABLE IF NOT EXISTS `mod_tier0_trainers_backup` (
  `CreatureId` int unsigned NOT NULL,
  `TrainerId` int unsigned NOT NULL,
  PRIMARY KEY (`CreatureId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

INSERT IGNORE INTO `mod_tier0_trainers_backup` (`CreatureId`, `TrainerId`)
SELECT `CreatureId`, `TrainerId` FROM `creature_default_trainer`
WHERE `TrainerId` NOT BETWEEN 9500900 AND 9500999
AND `CreatureId` IN (514, 812, 908, 1103, 1215, 1218, 1241, 1292, 1317, 1346, 1355, 1385, 1386, 1458, 1470, 1473, 1632, 1651, 1676, 1680, 1681, 1683, 1699, 1700, 1701, 1702, 2114, 2132, 2327, 2367, 2390, 2391, 2399, 2627, 2798, 2834, 2836, 2837, 2856, 2998, 3001, 3004, 3007, 3009, 3011, 3013, 3026, 3028, 3069, 3087, 3136, 3137, 3174, 3175, 3179, 3181, 3185, 3290, 3332, 3345, 3347, 3355, 3357, 3363, 3365, 3373, 3399, 3404, 3478, 3494, 3523, 3549, 3555, 3557, 3603, 3604, 3605, 3606, 3607, 3703, 3704, 3964, 3965, 3967, 4156, 4160, 4193, 4204, 4210, 4211, 4212, 4213, 4254, 4258, 4552, 4573, 4576, 4588, 4591, 4596, 4598, 4611, 4614, 4616, 4898, 4900, 5127, 5137, 5150, 5153, 5157, 5159, 5161, 5174, 5177, 5392, 5482, 5493, 5499, 5502, 5511, 5513, 5518, 5564, 5566, 5690, 5695, 5759, 5784, 5938, 5939, 5943, 6094, 6287, 6288, 6289, 6290, 6291, 6292, 6295, 6297, 6299, 6306, 6387, 7087, 7088, 7089, 7946, 7948, 7949, 8128, 8144, 8146, 8153, 8736, 10993, 11017, 11025, 11031, 11037, 11052, 11072, 11073, 11074, 11097, 11098, 12025, 12030, 14740, 15400, 15501, 16160, 16161, 16253, 16272, 16273, 16277, 16278, 16366, 16367, 16633, 16640, 16642, 16644, 16662, 16663, 16667, 16669, 16688, 16692, 16723, 16724, 16725, 16726, 16728, 16729, 16731, 16736, 16752, 16763, 16774, 16780, 17101, 17214, 17215, 17222, 17245, 17246, 17424, 17434, 17441, 17442, 17487, 17488, 17983, 18018, 19478, 19775, 19778, 22477, 34708, 34710, 34711, 34712, 34713, 34714, 34785, 34786);

-- Blacksmithing: 17 NPCs -> TrainerId 9500902
UPDATE `creature_default_trainer` SET `TrainerId` = 9500902 WHERE `CreatureId` IN (514, 1241, 2836, 2998, 3136, 3174, 3355, 3478, 3557, 4258, 4596, 5511, 6299, 15400, 16669, 16724, 17245);

